import RNA, random, time, os
from multiprocessing import Pool

target = "....((((..(((((..((((..((((.....))))((((((...))).)))))))((((((.((.((.(((((....)).)))))))(((((.((.((.((....))))))(((((.(((....)).))).)))..)).)))))).))))))))(((.(((.(((.((((....))))))))))((((((((...))).)).))).)))))))"
N = len(target)
B="ACGU"

def seed():
    seq=["A"]*N
    stack=[]
    for i,c in enumerate(target):
        if c=="(":
            stack.append(i)
        elif c==")":
            j=stack.pop()
            seq[j]="G"; seq[i]="C"
    return "".join(seq)

def fold(s):
    fc=RNA.fold_compound(s)
    mfe_s,mfe_e=fc.mfe()
    return RNA.bp_distance(target,mfe_s), mfe_e

def worker(args):
    rng_seed, budget = args
    rng=random.Random(rng_seed)
    cur=list(seed())
    for i in range(N):
        if target[i]=="." and rng.random()<0.3:
            cur[i]=rng.choice(B)
    cur_d,_=fold("".join(cur))
    best=cur[:]; best_d=cur_d
    t0=time.time()
    T=2.0
    while time.time()-t0<budget and best_d>0:
        k=rng.choice([1,1,2])
        idxs=rng.sample(range(N),k)
        old=[cur[i] for i in idxs]
        for i in idxs:
            cur[i]=rng.choice(B)
        d,e=fold("".join(cur))
        if d<=cur_d or rng.random()<2.71828**((cur_d-d)/max(T,0.05)):
            cur_d=d
            if d<best_d:
                best_d=d; best=cur[:]
        else:
            for j,i in enumerate(idxs):
                cur[i]=old[j]
        T*=0.999
    return best_d, "".join(best)

if __name__=="__main__":
    ncpu=int(os.environ.get("NPROC","128"))
    budget=140
    with Pool(ncpu) as p:
        results=p.map(worker, [(s,budget) for s in range(ncpu*2)])
    results.sort()
    print("best_d", results[0][0])
    print("SEQ", results[0][1])
    open("/tmp/best_seq.txt","w").write(results[0][1])

